import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Let positive integers a_1, a_2, ..., a_{n_terms} form an increasing geometric progression. It is given that log_2(a_1) + log_2(a_2) + ... + log_2(a_{n_terms}) = {s_value}. Furthermore, for i = {square_index} the difference a_{i+1} - a_i is a perfect square, and for j = {cube_index} the difference a_{j+1} - a_j is a perfect cube. Also, a_{n_terms} - a_{n_terms-1} is not a perfect fourth power. Determine the value of a_1 + a_2 + ... + a_{n_terms}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate a GP of powers of 2 with ratio 2 (i.e., exponents form an arithmetic progression with step 1),
# then encode it only via constraints on logs and selected differences.
# Steps:
# 1) Choose n in [3,6].
# 2) Choose distinct indices i,j in {1,...,n-1}.
# 3) Solve CRT for x so that x+(i-1) is even (square) and x+(j-1) is divisible by 3 (cube).
# 4) Choose x = r + 6*t in a moderate range and ensure the final difference is not a perfect fourth power.
# 5) Set S = n*x + n*(n-1)//2 so that the product equals 2^S.

def solve_mod6(i, j):
    r2 = (i - 1) % 2  # x ≡ r2 (mod 2)
    r3 = (- (j - 1)) % 3  # x ≡ r3 (mod 3)
    for r in range(6):
        if r % 2 == r2 and r % 3 == r3:
            return r
    return None  # should not happen

attempts = 0
while True:
    attempts += 1
    if attempts > 1000:
        # Fallback deterministic choice
        n = 4
        i, j = 1, 2
    else:
        n = rng.randint(3, 6)
        # pick two distinct indices in 1..n-1
        choices = list(range(1, n))
        rng.shuffle(choices)
        i, j = choices[0], choices[1]
    r = solve_mod6(i, j)
    if r is None:
        continue
    # pick t so that x is moderate and the last difference exponent is not divisible by 4
    # x = r + 6*t
    # ensure 5 <= x <= 30 for balance
    t_candidates = list(range(1, 6))  # yields x in roughly [7, 36]
    rng.shuffle(t_candidates)
    x = None
    for t in t_candidates:
        candidate = r + 6 * t
        # last difference exponent is candidate + (n-2); avoid multiple of 4
        if (candidate + (n - 2)) % 4 != 0 and candidate >= 5 and candidate <= 30:
            x = candidate
            break
    if x is None:
        continue
    S = n * x + n * (n - 1) // 2
    # Optional: avoid overly large sums
    total_sum_est = (1 << x) * ((1 << n) - 1)
    if total_sum_est > 10**12:
        # too big; try again
        continue
    return {
        'n_terms': n,
        's_value': S,
        'square_index': i,
        'cube_index': j
    }

    def verifier(assign):
# Validate types
try:
    n = int(assign['n_terms'])
    S = int(assign['s_value'])
    i = int(assign['square_index'])
    j = int(assign['cube_index'])
except Exception:
    # invalid assignment
    return (False, None)
# Domain checks
if n < 3:
    # need at least 3 terms
    return (False, None)
if not (1 <= i <= n - 1 and 1 <= j <= n - 1):
    # indices out of range
    return (False, None)
if i == j:
    # must be distinct to enforce two independent constraints
    return (False, None)
# Core logical reconstruction:
# From product constraint: a_1 * ... * a_n = 2^S.
# For integers in a GP, write a_k = a * r^{k-1}. Then product = a^n * r^{n(n-1)/2}.
# Since product is a pure power of 2, a and r must themselves be powers of 2.
# Let a = 2^x and r = 2^y with integers x >= 0, y >= 1 (increasing GP).
# The sum condition gives S = n*x + y * n(n-1)/2.
# The square difference condition at index i:
# a_{i+1} - a_i = 2^{x + (i-1) y} * (2^y - 1) must be a perfect square.
# As 2^y - 1 is odd, its odd component must itself be a square; the only y >= 1 making 2^y - 1 a square is y = 1.
# We enforce y = 1 and check consistency.
y = 1
# Compute x from S = n*x + n(n-1)/2.
numerator = S - n * (n - 1) // 2
if numerator % n != 0:
    # x must be integer
    return (False, None)
x = numerator // n
if x < 0:
    return (False, None)
# Check the square and cube constraints using y = 1.
# With y = 1, a_{t+1} - a_t = 2^{x + (t-1)}.
# Square: exponent even -> x + (i-1) even.
# Cube: exponent divisible by 3 -> x + (j-1) ≡ 0 (mod 3).
if ((x + (i - 1)) % 2) != 0:
    # violates square condition
    return (False, None)
if ((x + (j - 1)) % 3) != 0:
    # violates cube condition
    return (False, None)
# Additional difficulty constraint: last difference is not a perfect fourth power
if ((x + (n - 2)) % 4) == 0:
    # would be a fourth power; reject
    return (False, None)
# All constraints satisfied. Compute sum of the GP:
# Sum = 2^x * (1 + 2 + ... + 2^{n-1}) = 2^x * (2^n - 1).
total_sum = (1 << x) * ((1 << n) - 1)
return (True, total_sum)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

